import { useState } from "react";

function App() {
  const [text, setText] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleExtract = async () => {
    if (!text) return;

    setLoading(true);

    try {
      const response = await fetch("http://127.0.0.1:8000/extract", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          job_description: text,
        }),
      });

      const data = await response.json();
      setResult(data);
    } catch (error) {
      console.error(error);
    }

    setLoading(false);
  };

  const isLimited = result?.skills?.includes("LIMIT REACHED");

  return (
    <div className="min-h-screen bg-slate-950 text-white p-6">

      {/* NAVBAR */}
      <div className="max-w-7xl mx-auto flex justify-between items-center mb-8">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl flex items-center justify-center font-bold text-lg">
            JS
          </div>
          <span className="text-xl font-semibold">JobSkills AI</span>
        </div>

        <button
          onClick={() => window.open("https://your-payment-link.com", "_blank")}
          className="px-5 py-2 bg-green-500 hover:bg-green-600 rounded-lg font-medium"
        >
          Upgrade
        </button>
      </div>

      {/* MAIN GRID */}
      <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-2 gap-6">

        {/* LEFT PANEL */}
        <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-xl">
          <h2 className="text-2xl font-bold mb-2">Analyze Job</h2>
          <p className="text-gray-400 mb-4">
            Paste a job description to extract skills and insights.
          </p>

          <textarea
            className="w-full h-56 p-4 rounded-xl bg-slate-950 border border-slate-700 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition"
            placeholder="Paste job description..."
            value={text}
            onChange={(e) => setText(e.target.value)}
          />

          <button
            onClick={handleExtract}
            className="w-full mt-4 py-4 rounded-xl bg-gradient-to-r from-indigo-500 to-purple-600 
            hover:from-indigo-600 hover:to-purple-700 transition font-semibold text-lg 
            shadow-lg shadow-indigo-500/30"
          >
            {loading ? "Analyzing..." : "Extract Insights"}
          </button>

          <p className="text-xs text-gray-500 mt-3 text-center">
            Get instant clarity on job requirements
          </p>
        </div>

        {/* RIGHT PANEL */}
        <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-xl">

          {!result && (
            <div className="h-full flex items-center justify-center text-gray-500">
              Results will appear here
            </div>
          )}

          {result && (
            <div className="space-y-6">

              {/* CORE */}
              <Section title="Core Skills" highlight items={result.core_skills} />

              {/* ALL */}
              <Section title="All Skills" items={result.skills} />

              {/* MISSING */}
              <div>
                <h3 className="text-lg font-semibold mb-2">Missing Skills</h3>

                {isLimited ? (
                  <div className="bg-slate-950 border border-slate-700 p-5 rounded-xl text-center">
                    <p className="text-gray-400 mb-3">
                      🔒 Upgrade to unlock missing skills
                    </p>
                    <button
                      onClick={() =>
                        window.open("https://your-payment-link.com", "_blank")
                      }
                      className="px-5 py-2 bg-green-500 hover:bg-green-600 rounded-lg font-medium"
                    >
                      Upgrade
                    </button>
                  </div>
                ) : (
                  <Section items={result.missing_skills} />
                )}
              </div>

              {/* LEVEL */}
              <div className="bg-slate-950 border border-slate-700 p-4 rounded-xl">
                <p className="text-sm text-gray-400">Experience Level</p>
                <p className="text-indigo-400 text-lg font-semibold">
                  {result.level}
                </p>
              </div>

            </div>
          )}
        </div>

      </div>
    </div>
  );
}

function Section({ title, items = [], highlight }) {
  return (
    <div>
      {title && <h3 className="text-lg font-semibold mb-2">{title}</h3>}
      <div className="flex flex-wrap gap-2">
        {(items || []).map((item, index) => (
          <span
            key={index}
            className={`px-3 py-1 rounded-full text-sm ${
              highlight
                ? "bg-indigo-500 text-white"
                : "bg-slate-700 text-gray-200"
            }`}
          >
            {item}
          </span>
        ))}
      </div>
    </div>
  );
}

export default App;
